<?php
/**
 * Its api for customer credit / debt.
 *
 * @package VitePos\Api\V1
 */

namespace VitePos\Api\V1;

use Appsbd\V1\libs\API_Data_Response;
use VitePos\Libs\API_Base;
use VitePos\Libs\VitePOS_Account_Service;
use VitePos\Libs\VitePOS_Collection_Order;
use VitePos\Libs\VitePOS_Credit_Settings;
use VitePos\Modules\POS_Settings;

/**
 * Class Pos_Credit_Api
 *
 * @package VitePos\Api\V1
 */
class Pos_Credit_Api extends API_Base {

	/**
	 * The set api base is generated by appsbd
	 *
	 * @return mixed|string
	 */
	public function set_api_base() {
		return 'credit';
	}

	/**
	 * The routes is generated by appsbd
	 *
	 * @return mixed|void
	 */
	public function routes() {
		$this->register_rest_route( 'POST', 'debt-summary', array( $this, 'debt_summary' ) );
		$this->register_rest_route( 'POST', 'debts', array( $this, 'debts' ) );
		$this->register_rest_route( 'POST', 'store-credit-log', array( $this, 'store_credit_log' ) );
		$this->register_rest_route( 'POST', 'payment', array( $this, 'payment' ) );
		$this->register_rest_route( 'POST', 'collect', array( $this, 'collect' ) );
		$this->register_rest_route( 'POST', 'set-limit', array( $this, 'set_limit' ) );
		$this->register_rest_route( 'POST', 'customers', array( $this, 'customers' ) );
		$this->register_rest_route( 'POST', 'report-outstanding', array( $this, 'report_outstanding' ) );
		$this->register_rest_route( 'POST', 'report-aging', array( $this, 'report_aging' ) );
		$this->register_rest_route( 'POST', 'report-outlet', array( $this, 'report_outlet' ) );
		$this->register_rest_route( 'POST', 'customer-ledger', array( $this, 'customer_ledger' ) );
		$this->register_rest_route( 'POST', 'outlet-ledger', array( $this, 'outlet_ledger' ) );
		$this->register_rest_route( 'POST', 'customer-fifo-log', array( $this, 'customer_fifo_log' ) );
	}

	/**
	 * Feature gate for credit endpoints. Returns a ready response when the debt
	 * feature is disabled (empty payload for reads, soft failure for writes), or
	 * null when enabled so the caller proceeds normally.
	 *
	 * @param bool  $is_write Treat as a mutating endpoint.
	 * @param mixed $empty    Empty payload shape for reads.
	 *
	 * @return \Appsbd\V1\libs\API_Response|null
	 */
	private function feature_gate( $is_write = false, $empty = array() ) {
		if ( VitePOS_Account_Service::is_feature_enabled() ) {
			return null;
		}
		if ( $is_write ) {
			$this->set_response( false, __( 'The Debt / On Account feature is disabled.', 'vitepos' ) );
		} else {
			$this->set_response( true, '', $empty );
		}
		return $this->response;
	}

	/**
	 * The set route permission is generated by appsbd
	 *
	 * @param \VitePos\Libs\any $route Its string.
	 *
	 * @return bool
	 */
	public function set_route_permission( $route ) {
		switch ( $route ) {
			case 'set-limit':
			case 'customers':
				return current_user_can( 'customer-edit' ) && current_user_can( 'pos-debt');
			
			
			
			case 'report-outstanding':
			case 'report-aging':
			case 'customer-ledger':
			case 'customer-fifo-log':
				return current_user_can( 'debt-menu' );
			case 'report-outlet':
			case 'outlet-ledger':
				return current_user_can( 'debt-outlet-report' );		
			default:
				return POS_Settings::is_pos_user();
		}
	}

	/**
	 * Summary totals + available credit for a customer.
	 *
	 * @return \Appsbd\V1\libs\API_Response
	 */
	public function debt_summary() {
		$gate = $this->feature_gate();   
		if ( $gate ) {
			return $gate;
		}
		$customer_id = (int) $this->get_payload( 'customer_id', 0 );
		if ( empty( $customer_id ) ) {
			$this->set_response( false, 'Customer is required.' );
			return $this->response;
		}
		$summary                   = VitePOS_Account_Service::get_summary( $customer_id );
		$credit                    = VitePOS_Account_Service::get_credit_info( $customer_id );
		$summary->credit_enabled   = $credit->credit_enabled;
		$summary->credit_limit     = $credit->credit_limit;
		$summary->available_credit = $credit->available_credit;
		$summary->store_credit     = $credit->store_credit;
		$this->set_response( true, '', $summary );
		return $this->response;
	}

	/**
	 * Ledger rows for a customer.
	 *
	 * @return \Appsbd\V1\libs\API_Response
	 */
	public function debts() {
		$gate = $this->feature_gate();   
		if ( $gate ) {
			return $gate;
		}
		$customer_id = (int) $this->get_payload( 'customer_id', 0 );
		$status      = $this->get_payload( 'status', null );
		if ( empty( $customer_id ) ) {
			$this->set_response( false, 'Customer is required.' );
			return $this->response;
		}
		$rows   = VitePOS_Account_Service::get_debt_rows( $customer_id, $status );
		$ledger = array();
		foreach ( $rows as $row ) {
			$row      = (object) $row;
			$ledger[] = (object) array(
				'id'               => (int) $row->id,
				'order_id'         => (int) $row->order_id,
				'created_at'       => appsbd_get_wp_datetime_with_format($row->created_at),
				'items'            => $this->get_order_items_text( $row->order_id ),
				'total_amount'     => (float) $row->total_amount,
				'paid_amount'      => (float) $row->paid_amount,
				'remaining_amount' => (float) $row->remaining_amount,
				'status'           => $row->status,
				'status_label'     => $row->status_label,
			);
		}
		$this->set_response( true, '', $ledger );
		return $this->response;
	}

	/**
	 * Store-credit statement (ledger) for a customer.
	 *
	 * @return \Appsbd\V1\libs\API_Response
	 */
	public function store_credit_log() {
		$gate = $this->feature_gate();   
		if ( $gate ) {
			return $gate;
		}
		$customer_id = (int) $this->get_payload( 'customer_id', 0 );
		if ( empty( $customer_id ) ) {
			$this->set_response( false, 'Customer is required.' );
			return $this->response;
		}
		$limit = (int) $this->get_payload( 'limit', 50 );
		$page  = (int) $this->get_payload( 'page', 1 );
		$this->set_response( true, '', VitePOS_Account_Service::get_statement( $customer_id, $limit, $page ) );
		return $this->response;
	}

	/**
	 * Record a repayment (specific invoice or bulk FIFO).
	 *
	 * @return \Appsbd\V1\libs\API_Response
	 */
	public function payment() {
		$gate = $this->feature_gate( true );   
		if ( $gate ) {
			return $gate;
		}
		$customer_id = (int) $this->get_payload( 'customer_id', 0 );
		$amount      = (float) $this->get_payload( 'amount', 0 );
		$method      = $this->get_payload( 'method', 'cash' );
		$note        = $this->get_payload( 'note', '' );
		$settle      = $this->get_payload( 'settle_remaining_as_credit', 'N' );

		$result = VitePOS_Collection_Order::create(
			array(
				'customer_id'                => $customer_id,
				'purpose'                    => 'D',
				'amount'                     => $amount,
				'method'                     => $method,
				'note'                       => $note,
				'settle_remaining_as_credit' => ( 'Y' === $settle ),
				'outlet_id'                  => $this->get_outlet_id(),
				'counter_id'                 => $this->get_counter_id(),
			)
		);
		if ( ! $result->is_ok ) {
			$this->add_error( $result->message );
			$this->set_response( false, $result->message );
			return $this->response;
		}
		$this->add_info( 'Repayment recorded successfully' );
		$this->set_response(
			true,
			'',
			(object) array(
				'order_id' => $result->order_id,
				'summary'  => VitePOS_Account_Service::get_summary( $customer_id ),
			)
		);
		return $this->response;
	}

	/**
	 * Record a store-credit top-up or debt collection as a completed WooCommerce
	 * order (built by VitePOS_Collection_Order) and apply it to the ledger.
	 *
	 * @return \Appsbd\V1\libs\API_Response
	 */
	public function collect() {
		$gate = $this->feature_gate( true );   
		if ( $gate ) {
			return $gate;
		}
		$customer_id = (int) $this->get_payload( 'customer_id', 0 );
		$purpose     = $this->get_payload( 'purpose', 'C' );
		$amount      = (float) $this->get_payload( 'amount', 0 );
		$method      = $this->get_payload( 'method', 'cash' );
		$note        = $this->get_payload( 'note', '' );
		$settle      = $this->get_payload( 'settle_remaining_as_credit', 'N' );
		$target      = (int) $this->get_payload( 'target_debt_id', 0 );
		$tender      = $this->get_payload( 'tender', array() );
		if ( ! is_array( $tender ) ) {
			$tender = array();
		}

		$result = VitePOS_Collection_Order::create(
			array(
				'customer_id'                => $customer_id,
				'purpose'                    => $purpose,
				'amount'                     => $amount,
				'method'                     => $method,
				'tender'                     => $tender,
				'note'                       => $note,
				'settle_remaining_as_credit' => ( 'Y' === $settle ),
				
				
				'target_debt_id'             => $target,
				'outlet_id'                  => $this->get_outlet_id(),
				'counter_id'                 => $this->get_counter_id(),
			)
		);
		if ( ! $result->is_ok ) {
			$this->add_error( $result->message );
			$this->set_response( false, $result->message );
			return $this->response;
		}
		
		
		
		$this->set_response( true, '', $result->details );
		return $this->response;
	}

	/**
	 * Admin: enable credit and set a per-customer limit.
	 *
	 * @return \Appsbd\V1\libs\API_Response
	 */
	public function set_limit() {
		$gate = $this->feature_gate( true );   
		if ( $gate ) {
			return $gate;
		}
		$customer_id = (int) $this->get_payload( 'customer_id', 0 );
		$enabled     = $this->get_payload( 'enabled', 'N' );
		$limit       = $this->get_payload( 'limit', null );
		if ( empty( $customer_id ) ) {
			$this->set_response( false, 'Customer is required.' );
			return $this->response;
		}
		if ( VitePOS_Credit_Settings::set_customer_credit( $customer_id, $enabled, $limit ) ) {
			$this->add_info( 'Credit settings updated' );
			$this->set_response( true, '', VitePOS_Credit_Settings::get_credit_info( $customer_id ) );
		} else {
			$this->set_response( false, 'Failed to update credit settings.' );
		}
		return $this->response;
	}

	/**
	 * Admin: credit-customers manager list.
	 *
	 * @return API_Data_Response
	 */
	public function customers() {
		$gate = $this->feature_gate();   
		if ( $gate ) {
			return $gate;
		}
		$page          = (int) $this->get_payload( 'page', 1 );
		$limit         = (int) $this->get_payload( 'limit', 20 );
		$search        = $this->get_payload( 'search', '' );
		$target_roles  = array( 'customer', 'subscriber' );
		$response_data = new API_Data_Response();
		$args          = array(
			'role__in'    => $target_roles,
			'count_total' => true,
			'number'      => $limit,
			'paged'       => $page,
		);
		if ( ! empty( $search ) ) {
			$args['search']         = '*' . $search . '*';
			$args['search_columns'] = array( 'user_login', 'user_email', 'display_name' );
		}
		$user_search = new \WP_User_Query( wp_parse_args( $args ) );
		$total       = $user_search->get_total();
		$rows        = array();
		foreach ( $user_search->get_results() as $user ) {
			$credit = VitePOS_Credit_Settings::get_credit_info( $user->ID );
			$rows[] = (object) array(
				'customer_id'    => $user->ID,
				'name'           => trim( $user->first_name . ' ' . $user->last_name ) ? trim( $user->first_name . ' ' . $user->last_name ) : $user->user_nicename,
				'email'          => $user->user_email,
				'credit_enabled' => $credit->credit_enabled,
				'credit_limit'   => $credit->credit_limit,
				'current_debt'   => $credit->current_debt,
			);
		}
		$response_data->limit = $limit;
		$response_data->page  = $page;
		if ( $response_data->set_total_records( $total ) ) {
			$response_data->rowdata = $rows;
		}
		return $response_data;
	}

	/**
	 * Outstanding-debt / top-debtors report.
	 *
	 * @return \Appsbd\V1\libs\API_Response
	 */
	public function report_outstanding() {
		$gate = $this->feature_gate();   
		if ( $gate ) {
			return $gate;
		}
		$limit  = (int) $this->get_payload( 'limit', 50 );
		$order  = $this->get_payload( 'order', 'DESC' );
		$search = trim( (string) $this->get_payload( 'search', '' ) );
		$rows   = VitePOS_Account_Service::get_outstanding_report( $limit, $order, $search );
		$report = array();
		foreach ( $rows as $row ) {
			$row               = (object) $row;
			$row->outstanding  = (float) $row->outstanding;
			$row->store_credit = (float) $row->store_credit;
			$row->debt_count   = (int) $row->debt_count;
			$report[]         = $row;
		}
		$this->set_response( true, '', $report );
		return $this->response;
	}

	/**
	 * Debt aging report.
	 *
	 * @return \Appsbd\V1\libs\API_Response
	 */
	public function report_aging() {
		$gate = $this->feature_gate();   
		if ( $gate ) {
			return $gate;
		}
		$this->set_response( true, '', VitePOS_Account_Service::get_aging_report() );
		return $this->response;
	}

	/**
	 * Outlet-wise debit/credit summary report.
	 *
	 * @return \Appsbd\V1\libs\API_Response
	 */
	public function report_outlet() {
		$gate = $this->feature_gate();   
		if ( $gate ) {
			return $gate;
		}
		$rows   = VitePOS_Account_Service::get_outlet_report();
		$report = array();
		foreach ( $rows as $row ) {
			$row      = (array) $row;
			$report[] = (object) array(
				'outlet_id'    => (int) $row['outlet_id'],
				'outlet_name'  => $row['outlet_name'],
				'entry_count'  => (int) $row['entry_count'],
				'total_debit'  => (float) $row['total_debit'],
				'total_credit' => (float) $row['total_credit'],
				'net'          => (float) $row['net'],
			);
		}
		$this->set_response( true, '', $report );
		return $this->response;
	}

	/**
	 * Per-customer unified debit/credit ledger plus the header summary, returned in
	 * one round-trip ( { rowdata, records, summary } ).
	 *
	 * @return \Appsbd\V1\libs\API_Response
	 */
	public function customer_ledger() {
		$gate = $this->feature_gate();   
		if ( $gate ) {
			return $gate;
		}
		$customer_id = (int) $this->get_payload( 'customer_id', 0 );
		if ( empty( $customer_id ) ) {
			$this->set_response( false, 'Customer is required.' );
			return $this->response;
		}
		$limit = (int) $this->get_payload( 'limit', 100000 );
		$page  = (int) $this->get_payload( 'page', 1 );
		$total = VitePOS_Account_Service::count_statement( $customer_id );
		$this->set_response(
			true,
			'',
			(object) array(
				'rowdata' => $this->build_ledger_rows( $customer_id, $limit, $page ),
				'records' => (int) $total,
				'summary' => VitePOS_Account_Service::get_summary( $customer_id ),
			)
		);
		return $this->response;
	}

	/**
	 * Debit/credit ledger log for a single outlet ( { rowdata, records } ).
	 *
	 * @return \Appsbd\V1\libs\API_Response
	 */
	public function outlet_ledger() {
		$gate = $this->feature_gate();   
		if ( $gate ) {
			return $gate;
		}
		$outlet_id = (int) $this->get_payload( 'outlet_id', 0 );
		$limit     = (int) $this->get_payload( 'limit', 100000 );
		$page      = (int) $this->get_payload( 'page', 1 );
		$total     = VitePOS_Account_Service::count_outlet_ledger( $outlet_id );
		$rows      = $total > 0
			? VitePOS_Account_Service::get_outlet_ledger( $outlet_id, $limit, $page )
			: array();
		$this->set_response(
			true,
			'',
			(object) array(
				'rowdata' => $this->decorate_ledger_rows( $rows ),
				'records' => (int) $total,
			)
		);
		return $this->response;
	}

	/**
	 * Per-customer FIFO allocation log ( { rows, summary } ).
	 *
	 * @return \Appsbd\V1\libs\API_Response
	 */
	public function customer_fifo_log() {
		$gate = $this->feature_gate();   
		if ( $gate ) {
			return $gate;
		}
		$customer_id = (int) $this->get_payload( 'customer_id', 0 );
		if ( empty( $customer_id ) ) {
			$this->set_response( false, 'Customer is required.' );
			return $this->response;
		}
		$log  = VitePOS_Account_Service::get_fifo_log( $customer_id );
		$rows = array();
		foreach ( $log['rows'] as $row ) {
			$rows[] = (object) array(
				'order_id'   => (int) $row['order_id'],
				'created_at' => appsbd_get_wp_datetime_with_format($row['created_at']),
				'amount'     => (float) $row['amount'],
				'applied'    => (float) $row['applied'],
				'remaining'  => (float) $row['remaining'],
				'age_days'   => (int) $row['age_days'],
				'status'     => $row['status'],
			);
		}
		$this->set_response(
			true,
			'',
			(object) array(
				'rows'    => $rows,
				'summary' => $log['summary'],
			)
		);
		return $this->response;
	}

	/**
	 * Build the unified debit/credit ledger rows for a customer (frontend shape).
	 *
	 * Mirrors POS_Credit::build_ledger_rows(): maps each account-statement entry onto
	 * the field names the ledger modal binds to and derives a human "Description".
	 *
	 * @param int $customer_id Customer id.
	 * @param int $limit Page size.
	 * @param int $page Page (1-based).
	 *
	 * @return array Array of row objects.
	 */
	private function build_ledger_rows( $customer_id, $limit = 50, $page = 1 ) {
		$rows   = VitePOS_Account_Service::get_statement( $customer_id, $limit, $page );
		$ledger = array();
		$index  = ( max( 1, $page ) - 1 ) * max( 1, $limit );
		$labels = array(
			'credit_topup'  => 'Store credit added',
			'debt_repay'    => 'Repayment',
			'debt_incur'    => 'On-account purchase',
			'credit_redeem' => 'Store credit used',
		);
		foreach ( $rows as $row ) {
			$entry_type = isset( $row['entry_type'] ) ? $row['entry_type'] : '';
			$title      = isset( $labels[ $entry_type ] )
				? $labels[ $entry_type ]
				: ( 'C' === $row['type'] ? 'Store credit added' : 'Store credit used' );
			$ledger[]   = (object) array(
				'id'          => ++$index,
				'type'        => $row['type'],
				'entry_type'  => $entry_type,
				'amount'      => (float) $row['amount'],
				'pre_balance' => isset( $row['prev_balance'] ) ? (float) $row['prev_balance'] : 0.0,
				'balance'     => (float) $row['balance'],
				'order_id'    => isset( $row['order_id'] ) ? (int) $row['order_id'] : 0,
				'title'       => $title,
				'note'        => $row['note'],
				'created_at'  => appsbd_get_wp_datetime_with_format($row['created_at']),
			);
		}
		return $ledger;
	}

	/**
	 * Map outlet-ledger rows onto the frontend field names (mirrors
	 * POS_Credit::decorate_ledger_rows()).
	 *
	 * @param array $rows Statement-style rows from the account service.
	 *
	 * @return array Array of row objects.
	 */
	private function decorate_ledger_rows( $rows ) {
		$labels = array(
			'credit_topup'  => 'Store credit added',
			'debt_repay'    => 'Repayment',
			'debt_incur'    => 'On-account purchase',
			'credit_redeem' => 'Store credit used',
		);
		$index  = 0;
		$ledger = array();
		foreach ( $rows as $row ) {
			$entry_type = isset( $row['entry_type'] ) ? $row['entry_type'] : '';
			$title      = isset( $labels[ $entry_type ] )
				? $labels[ $entry_type ]
				: ( 'C' === $row['type'] ? 'Store credit added' : 'Store credit used' );
			$user       = get_userdata( (int) $row['customer_id'] );
			$ledger[]   = (object) array(
				'id'            => ++$index,
				'type'          => $row['type'],
				'entry_type'    => $entry_type,
				'customer_id'   => (int) $row['customer_id'],
				'customer_name' => $user->first_name ?  ($user->first_name . ' ' . $user->last_name) : $user->display_name,
				'amount'        => (float) $row['amount'],
				'pre_balance'   => isset( $row['prev_balance'] ) ? (float) $row['prev_balance'] : 0.0,
				'balance'       => (float) $row['balance'],
				'order_id'      => isset( $row['order_id'] ) ? (int) $row['order_id'] : 0,
				'title'         => $title,
				'note'          => $row['note'],
				'created_at'    =>  appsbd_get_wp_datetime_with_format($row['created_at']),
			);
		}
		return $ledger;
	}

	/**
	 * Build a short "items purchased" string from a WC order.
	 *
	 * @param int $order_id Its order_id param.
	 *
	 * @return string
	 */
	private function get_order_items_text( $order_id ) {
		if ( empty( $order_id ) ) {
			return '';
		}
		$order = wc_get_order( $order_id );
		if ( ! $order ) {
			return '';
		}
		$parts = array();
		foreach ( $order->get_items() as $item ) {
			$parts[] = $item->get_quantity() . '× ' . $item->get_name();
		}
		return implode( ', ', $parts );
	}
}
